mapper.select:
SELECT * FROM (
    SELECT * FROM ANS_BREAKING_NEWS WHERE TITLE LIKE CONCAT('%', #{keyword}, '%') 
    UNION 
    SELECT * FROM ANS_MAIN_NEWS WHERE TITLE LIKE CONCAT('%', #{keyword}, '%')
) AS search_results 
LIMIT #{pageSize} OFFSET #{offset}

SELECT TITLE, SMR, PRESS, IMG_URL1, URL
FROM ANS_MAIN_NEWS
WHERE idx=#{idx}

SELECT IDX, TITLE, SMR, PRESS, IMG_URL1, URL
FROM ANS_BREAKING_NEWS  
WHERE idx=#{idx}

SELECT TEXT
FROM ANS_MAIN_NEWS  
WHERE idx=#{idx}

SELECT TEXT
FROM ANS_BREAKING_NEWS  
WHERE idx=#{idx}

SELECT COUNT(*) FROM ANS_FAV
WHERE ID = #{id}
AND (MAIN_IDX = #{idx} OR BREAKING_IDX = #{idx})

mapper.delete:
DELETE FROM ANS_FAV
WHERE ID = #{id}
AND (MAIN_IDX = #{idx} OR BREAKING_IDX = #{idx})

mapper.select:
SELECT idx, id, main_idx, breaking_idx, create_dt
FROM ANS_FAV
WHERE id = #{id}
ORDER BY create_dt DESC
LIMIT #{offset}, #{pageSize}

SELECT idx, title, smr, press
FROM ANS_MAIN_NEWS
WHERE idx = #{idx}

SELECT idx, title, smr, press
FROM ANS_BREAKING_NEWS
WHERE idx = #{idx}
